    if (g.status !== 'accepted') { toast('info', '这场通告已经不在了'); return; }
    if (st.act.restUntil > st.day) { toast('warning', '身体还没缓过来（到 ' + C.mdShort(st.act.restUntil) + '），今天进不了棚'); return; }
    if (st.act.checkupUntil < st.day) { toast('warning', '体检报告过期了：先去钱包续体检，再进棚'); return; }
    var sid = g.scriptId;
