    var p = 0.78 - Math.min(0.3, (f.ng || 0) * 0.04) + (f.reEdits ? 0.15 : 0), pass = C.rndFloat() < p;
    var after = C.afterMishaps(), extra = !pass ? C.pick(after.filter(function (x) { return /打码|审核/.test(x); })) || '打码师傅漏了一帧' : '';
    await save(function (s) {
      var x = s.dir.films.find(function (y) { return y.id === fid; }); if (!x) return;
      if (pass) { x.status = 'waiting'; x.reviewDay = s.day; addNews(s, '《' + x.title + '》过了审查中心，等新法的四个月（' + C.mdShort(x.releaseDay) + '）上架'); }
      else { x.status = 'rejected'; x.rejectWhy = extra; addNews(s, '《' + x.title + '》被方正打回：' + extra); }
    });
    toast(pass ? 'success' : 'warning', pass ? '方正盖章了：《' + f.title + '》过审，' + C.mdText(f.releaseDay) + ' 上架' : '方正打回：' + extra + '。重剪要 ' + money(E.reEdit));
