    '  --pc-amber:#e2a648;--pc-amber-ink:#1d1405;--pc-amber-soft:rgba(226,166,72,.13);--pc-red:#e5483d;--pc-green:#7fb069;--pc-shadow:0 22px 60px rgba(0,0,0,.65);',
