        var raw = rawText(await genRaw({ user_input: user, should_silence: true, max_chat_history: 0, ordered_prompts: [{ role: 'system', content: C.SANDBOX_FICTION }, { role: 'system', content: subst(sys) }].concat(hist), generation_id: 'pianchang-k-' + Date.now().toString(36) + attempt }));
        var t = C.cleanRaw(raw).split('\n').map(function (l) { return l.replace(/^\s*(?:柯大河|小柯)\s*[：:]\s*/, '').trim(); }).filter(Boolean).join('\n');
